# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/64q_backbench_frontbench_split.R
# 64q_backbench_frontbench_split.R
#
# PJ, 7 Sep: the self-regarding measure's career/office terms fire mechanically
# off HOLDING a ministerial/shadow role ("as Secretary of State..." is the
# institutionally correct form of address, not a behavioural choice), and
# Blumenau & Damiani's own paper finds the frontbench speaking "bonus" over
# backbenchers has DECLINED 1979-2019 — so part of the declining self-
# regarding trend could be compositional (backbenchers getting more airtime
# now) rather than behavioural (individual MPs talking about themselves less).
#
# TEST: reproduce the EXACT same 1979-2019 sample as 64n (same seed, same
# filter — literally the same speeches already scored for the headline
# series), split by whether the speaker held a government or opposition
# position at the time (Blumenau's own `holds_government_position` /
# `holds_opposition_position` fields), and compute the self-regarding ratio
# separately for backbenchers vs frontbenchers. If the declining trend
# survives WITHIN backbenchers alone, it's not just a composition effect.
#
# 2020-25 has no role metadata in our own API pull — this split covers
# 1979-2019 only (Blumenau).
#
# OUTPUT: console only.

suppressMessages({library(dplyr); library(readr); library(stringr); library(purrr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
DATA_IN   <- file.path(WKBD_ROOT, "sources_raw/blumenau_damiani_commons_speeches_1979_2019/extracted/out")

career_terms <- c(
  "my role", "my position", "my appointment", "my department",
  "my portfolio", "my responsibilities", "my tenure", "my office",
  "my capacity", "my ministerial", "my shadow", "my career",
  "as minister", "as secretary of state", "as chancellor",
  "as home secretary", "as foreign secretary", "as prime minister"
)
policy_terms <- c(
  "my constituents", "my constituency", "people in my",
  "the evidence", "the research shows", "the data",
  "the public", "communities", "families",
  "workers", "businesses", "this policy", "the policy",
  "the bill", "the legislation", "the government must",
  "we must", "we should", "we need to"
)
score_speech <- function(text, terms) {
  text_lower <- tolower(text)
  sum(str_count(text_lower, fixed(terms)))
}

years <- 1979:2019
results <- vector("list", length(years))

for (i in seq_along(years)) {
  yr <- years[i]
  f <- file.path(DATA_IN, sprintf("%d.csv", yr))
  if (!file.exists(f)) next

  d <- read_csv(f, show_col_types = FALSE, progress = FALSE,
                col_select = c(hdate, body, n_words, holds_government_position, holds_opposition_position)) |>
    filter(!is.na(body), nchar(body) > 300)

  set.seed(42)
  samp <- d |> slice_sample(n = min(1500, nrow(d)))  # SAME sample as 64n, same seed

  scored <- samp |>
    mutate(
      n_words_calc = str_count(body, "\\S+"),
      n_career   = map_int(body, score_speech, career_terms),
      n_policy   = map_int(body, score_speech, policy_terms),
      self_ratio = (n_career + 0.5) / (n_career + n_policy + 1),
      is_frontbench = coalesce(holds_government_position, FALSE) | coalesce(holds_opposition_position, FALSE)
    ) |>
    filter(n_words_calc >= 50)

  by_group <- scored |>
    group_by(is_frontbench) |>
    summarise(n = n(), ratio = mean(self_ratio), .groups = "drop")

  bb <- by_group |> filter(!is_frontbench)
  fb <- by_group |> filter(is_frontbench)

  results[[i]] <- tibble(
    year = yr,
    n_backbench = if (nrow(bb) > 0) bb$n else NA_integer_,
    backbench_ratio = if (nrow(bb) > 0) bb$ratio else NA_real_,
    n_frontbench = if (nrow(fb) > 0) fb$n else NA_integer_,
    frontbench_ratio = if (nrow(fb) > 0) fb$ratio else NA_real_
  )
  cat(sprintf("%d: backbench n=%s ratio=%.3f | frontbench n=%s ratio=%.3f\n",
              yr,
              ifelse(nrow(bb)>0, as.character(bb$n), "NA"), ifelse(nrow(bb)>0, bb$ratio, NA),
              ifelse(nrow(fb)>0, as.character(fb$n), "NA"), ifelse(nrow(fb)>0, fb$ratio, NA)))
}

annual <- bind_rows(results) |> arrange(year)

period <- function(d, y0, y1, col) d |> filter(year >= y0, year <= y1) |> summarise(m = mean({{col}}, na.rm = TRUE)) |> pull(m)

cat("\n=== PERIOD MEANS ===\n")
for (rng in list(c(1979, 1988), c(1989, 1997), c(1998, 2009), c(2010, 2019))) {
  bb_p <- period(annual, rng[1], rng[2], backbench_ratio)
  fb_p <- period(annual, rng[1], rng[2], frontbench_ratio)
  cat(sprintf("%d-%d: Backbench %.1f%%  |  Frontbench %.1f%%  |  Frontbench premium %+.1fpp\n",
              rng[1], rng[2], bb_p*100, fb_p*100, (fb_p-bb_p)*100))
}

cat("\n=== TREND CHECK: 1979-88 vs 2010-19, within each group ===\n")
bb_early <- period(annual, 1979, 1988, backbench_ratio); bb_late <- period(annual, 2010, 2019, backbench_ratio)
fb_early <- period(annual, 1979, 1988, frontbench_ratio); fb_late <- period(annual, 2010, 2019, frontbench_ratio)
cat(sprintf("Backbench:  %.1f%% -> %.1f%%  (change %+.1fpp)\n", bb_early*100, bb_late*100, (bb_late-bb_early)*100))
cat(sprintf("Frontbench: %.1f%% -> %.1f%%  (change %+.1fpp)\n", fb_early*100, fb_late*100, (fb_late-fb_early)*100))

cat("\n=== Composition check: frontbench share of sampled speeches ===\n")
comp <- annual |> mutate(fb_share = n_frontbench / (n_frontbench + n_backbench))
print(comp |> filter(year %in% c(1979,1988,1989,1997,1998,2009,2010,2019)) |> select(year, fb_share))

OUT <- file.path(WKBD_ROOT, "online_appendix/ch3_backbench_frontbench_split.csv")
dir.create(dirname(OUT), showWarnings = FALSE)
write_csv(comp, OUT)
cat("\nSaved:", OUT, "\n")
